import numpy as np, pandas as pd
from pandarallel import pandarallel
pandarallel.initialize(nb_workers=2, progress_bar=False, use_memory_fs=None, verbose=0)

df = pd.DataFrame({"a": pd.Series([], dtype="int64"), "b": pd.Series([], dtype="float64")})
print("sequential:", repr(df.groupby("a").b.rolling(2).apply(np.sum, raw=True)))
try:
    df.groupby("a").b.rolling(2).parallel_apply(np.sum, raw=True)
except Exception as e:
    print("parallel rolling raised:", type(e).__name__, e)
try:
    df.groupby("a").b.expanding().parallel_apply(np.sum, raw=True)
except Exception as e:
    print("parallel expanding raised:", type(e).__name__, e)
